using System.Runtime.InteropServices;
using Microsoft.Win32.SafeHandles;

namespace ProcX.Infrastructure.Native;

/// <summary>
/// Hand-written kernel32 declarations that work with raw handle values from other processes,
/// which do not fit the <see cref="SafeHandle"/>-based overloads generated by CsWin32.
/// </summary>
internal static partial class Kernel32
{
    /// <summary>
    /// The pseudo-handle of the current process.
    /// </summary>
    public static readonly nint CurrentProcess = -1;

    /// <summary>
    /// <c>PROCESS_QUERY_LIMITED_INFORMATION</c>.
    /// </summary>
    public const uint ProcessQueryLimitedInformation = 0x1000;

    /// <summary>
    /// <c>THREAD_QUERY_LIMITED_INFORMATION</c>.
    /// </summary>
    public const uint ThreadQueryLimitedInformation = 0x0800;

    /// <summary>
    /// Duplicates a handle owned by another process into the current process.
    /// </summary>
    /// <param name="sourceProcess">The owning process, opened with <c>PROCESS_DUP_HANDLE</c>.</param>
    /// <param name="sourceHandle">The handle value in the owning process.</param>
    /// <param name="targetProcess">The receiving process (<see cref="CurrentProcess"/>).</param>
    /// <param name="targetHandle">Receives the new handle; must be closed with <see cref="CloseHandle"/>.</param>
    /// <param name="desiredAccess">The access for the new handle.</param>
    /// <param name="inheritHandle">Whether the new handle is inheritable.</param>
    /// <param name="options">The <c>DUPLICATE_*</c> options.</param>
    /// <returns><see langword="true"/> on success.</returns>
    [LibraryImport("kernel32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    public static partial bool DuplicateHandle(
        SafeFileHandle sourceProcess,
        nint sourceHandle,
        nint targetProcess,
        out nint targetHandle,
        uint desiredAccess,
        [MarshalAs(UnmanagedType.Bool)] bool inheritHandle,
        uint options);

    /// <summary>
    /// Closes a raw handle.
    /// </summary>
    /// <param name="handle">The handle.</param>
    /// <returns><see langword="true"/> on success.</returns>
    [LibraryImport("kernel32.dll")]
    [return: MarshalAs(UnmanagedType.Bool)]
    public static partial bool CloseHandle(nint handle);

    /// <summary>
    /// Gets the process ID of a process handle.
    /// </summary>
    /// <param name="process">A handle with <c>PROCESS_QUERY_LIMITED_INFORMATION</c>.</param>
    /// <returns>The PID, or 0 on failure.</returns>
    [LibraryImport("kernel32.dll")]
    public static partial uint GetProcessId(nint process);

    /// <summary>
    /// Gets the thread ID of a thread handle.
    /// </summary>
    /// <param name="thread">A handle with <c>THREAD_QUERY_LIMITED_INFORMATION</c>.</param>
    /// <returns>The TID, or 0 on failure.</returns>
    [LibraryImport("kernel32.dll")]
    public static partial uint GetThreadId(nint thread);

    /// <summary>
    /// Gets the owning process ID of a thread handle.
    /// </summary>
    /// <param name="thread">A handle with <c>THREAD_QUERY_LIMITED_INFORMATION</c>.</param>
    /// <returns>The PID, or 0 on failure.</returns>
    [LibraryImport("kernel32.dll")]
    public static partial uint GetProcessIdOfThread(nint thread);
}
